def minPath(grid, k):
    n = len(grid)

    # Find the starting position (cell with value 1)
    start = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break

    path = [1]
    r, c = start

    for _ in range(k - 1):
        best_val = float('inf')
        best_pos = None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] < best_val:
                    best_val = grid[nr][nc]
                    best_pos = (nr, nc)
        path.append(best_val)
        r, c = best_pos

    return path
